#include <stdio.h>
#include <stdlib.h>

static char outbuf[1 << 20];
static int outidx = 0;

static void flush_out(void) {
    if (outidx > 0) {
        fwrite(outbuf, 1, outidx, stdout);
        outidx = 0;
    }
}

static void write_char(char c) {
    if (outidx == (int)sizeof(outbuf)) {
        flush_out();
    }
    outbuf[outidx++] = c;
}

static void write_int(int x) {
    if (x == 0) {
        write_char('0');
        return;
    }

    char s[12];
    int n = 0;

    while (x > 0) {
        s[n++] = (char)('0' + (x % 10));
        x /= 10;
    }

    while (n > 0) {
        write_char(s[--n]);
    }
}

int main(void) {
    int N, M, P;

    if (scanf("%d %d %d", &N, &M, &P) != 3) {
        return 0;
    }

    int *row = (int *)malloc((N + 1) * sizeof(int));
    int *col = (int *)malloc((M + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) {
        row[i] = i;
    }

    for (int j = 1; j <= M; j++) {
        col[j] = j;
    }

    for (int k = 0; k < P; k++) {
        char op;
        int a, b;

        scanf(" %c %d %d", &op, &a, &b);

        if (op == 'L') {
            int tmp = row[a];
            row[a] = row[b];
            row[b] = tmp;
        } else {
            int tmp = col[a];
            col[a] = col[b];
            col[b] = tmp;
        }
    }

    for (int i = 1; i <= N; i++) {
        int base = (row[i] - 1) * M;

        for (int j = 1; j <= M; j++) {
            if (j > 1) {
                write_char(' ');
            }
            write_int(base + col[j]);
        }

        write_char('\n');
    }

    flush_out();

    free(row);
    free(col);

    return 0;
}
